use std :: str :: FromStr ; use forge_domain :: { ChatCompletionMessage , Content , FinishReason , TokenCount , ToolCallFull , ToolCallId , ToolCallPart , ToolName , Usage , } ; use serde :: { Deserialize , Serialize } ; use super :: tool_choice :: FunctionType ; use crate :: dto :: openai :: ReasoningDetail ; use crate :: dto :: openai :: error :: { Error , ErrorCode , ErrorResponse } ; use anyhow :: Context ; use forge_domain :: ChatCompletionMessage ; use super :: * ; impl ResponseMessage { # [doc = " Returns the reasoning text. When both `reasoning` and"] # [doc = " `reasoning_content` are present, the longer non-empty value is"] # [doc = " returned; otherwise whichever is non-empty is used."] pub fn reasoning (& self) -> Option < & str > { match (self . reasoning . as_deref () , self . reasoning_content . as_deref ()) { (Some (a) , Some (b)) => { let a = a . trim () ; let b = b . trim () ; match (a . is_empty () , b . is_empty ()) { (true , _) => Some (b) . filter (| s | ! s . is_empty ()) , (_ , true) => Some (a) . filter (| s | ! s . is_empty ()) , _ => Some (if b . len () > a . len () { b } else { a }) , } } (Some (a) , None) => Some (a) . filter (| s | ! s . trim () . is_empty ()) , (None , Some (b)) => Some (b) . filter (| s | ! s . trim () . is_empty ()) , (None , None) => None , } } }